#pragma once

#include <cstdint>
#include <string_view>
#include <vector>

#include "btf/btf.h"

namespace bpftrace::btf {

// A type used by a helper prototype. Types refer to other types by their index
// in `helper_types`, where index 0 is `void`.
struct HelperType {
  enum class Kind : uint8_t {
    Integer,
    Typedef,
    Pointer,
    Const,
    ForwardStruct,
  };
  Kind kind;
  std::string_view name;
  uint32_t size = 0;
  int encoding = 0;
  uint32_t type = 0;
};

struct HelperProto {
  std::string_view name;
  uint32_t return_type;
  std::vector<uint32_t> args;
};

// Generated by scripts/generate_helper_protos.py.
extern const std::vector<HelperType> helper_types;
extern const std::vector<HelperProto> helper_protos;

// Returns a type system with a global `Function` for each BPF helper declared
// by libbpf, with the prototype from libbpf's declaration.
Result<Types> load_helper_protos();

} // namespace bpftrace::btf
